FILES={'backend/app/tests/test_food_recipe_domain.py': '', 'backend/app/tests/test_food_recipe_application.py': '', 'backend/app/tests/test_food_recipe_migration.py': '', 'backend/app/tests/test_food_recipe_seed.py': '', 'scripts/build_pr4_recipe_seed.py': '', 'data/seed/recipes/README.md': ''}
for raw,payload in FILES.items():
 p=Path(raw); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(lzma.decompress(base64.b64decode(payload)))
